{
  "tool": {
    "category": "doc",
    "description": "Export a PDF ▸ Word (.docx), PowerPoint (.pptx, one slide per page), HTML (.html, one file with images inline) or RTF (.rtf), chosen by path's extension: text, headings, bold and italic. Word uses borderless inferred tables and positioned editable shapes on pages with artwork, rotated or large text; each source page retains its size. Font matching and vector graphics remain limited.",
    "destructive": false,
    "input_schema": {
      "additionalProperties": false,
      "properties": {
        "doc": {
          "description": "Document id from doc_open or doc_list.",
          "minimum": 1,
          "type": "integer"
        },
        "path": {
          "type": "string"
        }
      },
      "required": [
        "doc",
        "path"
      ],
      "type": "object"
    },
    "name": "doc_export_office",
    "read_only": false,
    "title": "Export to Word, PowerPoint, HTML or RTF"
  }
}

{
  "tool": {
    "category": "doc",
    "description": "Find faux redactions: opaque filled rectangles painted over text that is still extractable, and /Redact annotations that were marked but never applied. Paint-order and colour-aware: a rectangle counts only when painted after the text and dark enough to hide it (page backgrounds and light shading are not flagged). Each finding reports the 1-based page, the kind (covered-text or unapplied-mark), the rectangle (points from the top-left of the displayed page, like comment_list), and the hidden text. Fails closed: unreadable content is an error, never a clean bill. A properly applied redaction removes the text and never flags.",
    "destructive": false,
    "input_schema": {
      "additionalProperties": false,
      "properties": {
        "doc": {
          "description": "Document id from doc_open or doc_list.",
          "minimum": 1,
          "type": "integer"
        }
      },
      "required": [
        "doc"
      ],
      "type": "object"
    },
    "name": "doc_audit_redactions",
    "read_only": true,
    "title": "Audit faux redactions"
  }
}
